<?php foreach($priceItems as $i):$state=partnerPriceState($i);$open=partnerItemOpen($i);?><article class="b2b-price-row" data-price-row data-quantity="<?=$open?>" data-original-unit="<?=e((string)($i['original_unit_price']??$i['unit_price']))?>"><div class="b2b-price-row-heading"><div><h3><?=e($i['product_name'])?></h3><p><?=e($i['sku'])?> · Cijena se mijenja za <strong><?=$open?> kom.</strong></p></div><div><small>Trenutna cijena / kom.</small><strong><?=partnerMoney(cents($i['unit_price']))?></strong></div></div><?php if($open!==(int)$i['quantity']):?><p class="notice">Isporučeni i otkazani dio zadržava cijenu. Preostala količina će se izdvojiti u zasebnu stavku s novom cijenom.</p><?php endif;?><div class="b2b-price-controls"><label for="price-mode-<?=(int)$i['id']?>">Način obračuna<select id="price-mode-<?=(int)$i['id']?>" name="lines[<?=(int)$i['id']?>][mode]" data-price-mode><?php foreach(['discount'=>'Popust od osnovice','markup'=>'Marža / dodatak na osnovicu','fixed'=>'Ručna jedinična cijena','original'=>'Vrati uslove pri kreiranju'] as $mode=>$label):?><option value="<?=e($mode)?>" <?=$mode===$state['pricing_mode']?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label for="price-extra-<?=(int)$i['id']?>">Dodatni popust (%)<input id="price-extra-<?=(int)$i['id']?>" name="lines[<?=(int)$i['id']?>][extra_discount_rate]" type="text" inputmode="decimal" value="<?=e($state['extra_discount_rate'])?>" data-price-extra required></label><fieldset data-price-rule <?=$state['pricing_mode']==='fixed'?'disabled hidden':''?>><label for="price-base-<?=(int)$i['id']?>">Osnovica KM<input id="price-base-<?=(int)$i['id']?>" name="lines[<?=(int)$i['id']?>][base_price]" type="text" inputmode="decimal" value="<?=e($state['base_price'])?>" data-price-base required></label><label for="price-rate-<?=(int)$i['id']?>">Popust / marža (%)<input id="price-rate-<?=(int)$i['id']?>" name="lines[<?=(int)$i['id']?>][rate]" type="text" inputmode="decimal" value="<?=e($state['pricing_rate'])?>" data-price-rate required></label></fieldset><fieldset data-price-fixed <?=$state['pricing_mode']==='fixed'?'':'disabled hidden'?>><label for="price-fixed-<?=(int)$i['id']?>">Ručna cijena prije dodatnog popusta KM<input id="price-fixed-<?=(int)$i['id']?>" name="lines[<?=(int)$i['id']?>][fixed_price]" type="text" inputmode="decimal" value="<?=e($state['price_before_extra'])?>" data-price-fixed-value required></label></fieldset></div><p class="field-help">Kod popusta osnovica je prodajna cijena; kod marže unesite odgovarajuću nabavnu osnovicu. Možete koristiti decimalni zarez ili tačku.</p><div class="b2b-price-preview" aria-live="polite"><span>Nova cijena: <strong data-price-unit><?=partnerMoney(cents($i['unit_price']))?></strong> / kom.</span><span>Za <?=$open?> kom: <strong data-price-total><?=partnerMoney(cents($i['unit_price'])*$open)?></strong></span></div></article><?php endforeach;?></div><label for="price_note">Obrazloženje promjene cijena</label><textarea id="price_note" name="price_note" maxlength="1000" rows="3" required placeholder="Npr. dodatni rabat po dogovoru s radionicom"></textarea><button>Sačuvaj cijene i obavijesti saradnika</button><p class="field-help">Konačan obračun provjerava server. Cijene ranijih isporuka, količine, lager i način dostave se ne mijenjaju. Promjena se upisuje u historiju narudžbe.</p></form><?php endif;?></section>
